  "question_count": 1,
  "is_atomic": true,
  "atomic_questions": [
    "What is the objective of this production plan — for example, maximize the number of complete products you can assemble, minimize total production cost, or something else?"
  ],
  "rationale": "The response contains a single clarification question asking for the specific objective of the production plan, with examples provided to guide the answer."
}

{
  "action": "question",
  "question_count": 1,
